/**
 * Browser fixture Mod for the Fabric API client assembly test: a plain Cordis
 * plugin that imports only the Fabric client contract (`ctx.fabricClient`) and
 * contributes a client command and a UI-slot registration. The assembly spec
 * boots it through the real Loader over the real browser command/slot
 * services and observes both contributions.
 */

export const name = 'fabric-client-fixture-mod'
export const inject = ['fabricClient']

export function apply(ctx) {
  ctx.fabricClient.registerCommand({
    name: 'modclientcmd',
    description: 'fixture client command',
    available: () => true,
    ui: {
      kind: 'popupSelect',
      options: async () => [],
      onSelect: () => {},
    },
  })

  ctx.fabricClient.registerSlot({ name: 'root' }, () => null)
}
